  1	//! Clip timing operations: trims and rate changes with source and action bounds.
  2	
  3	use crate::edit_clip::clip_end;
  4	use crate::edit_speed_profile::profile_factors;
  5	use crate::model::{Clip, Project, Source};
  6	use crate::model_words::rebase_words;
  7	use crate::outcome::Outcome;
  8	use crate::recipe_graphic::graphic_advanced;
  9	use crate::source_window::source_advanced_through;
 10	use crate::time::Ticks;
 11	
 12	/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
 13	/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
 14	/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
 15	/// #41). The app reads it through `rc_speed_limits` and never retypes it.
 16	pub(crate) const SPEED_MIN: f64 = 0.1;
 17	pub(crate) const SPEED_MAX: f64 = 1000.0;
 18	
 19	/// The fastest a clip's audio still plays, in both pitch modes (spec §11
 20	/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
 21	/// clip's audio segment out (`evaluate.rs`); the video still runs to
 22	/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
 23	/// export's loudness pass never finishes for a keep-pitch clip that starts
 24	/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
 25	/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
 26	/// the mixer and an audio-only export, and are not the product's ceiling.
 27	pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;
 28	
 29	/// Every number about speed, as `rc_speed_limits` publishes it:
 30	/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
 31	pub(crate) fn speed_limits() -> serde_json::Value {
 32	    serde_json::json!({
 33	        "min": SPEED_MIN,
 34	        "max": SPEED_MAX,
 35	        "audio_max": AUDIO_SPEED_MAX,
 36	    })
 37	}
 38	
 39	impl Project {
 40	    /// Moves the clip's start edge to `to`, advancing the source in point
 41	    /// by `(to - start) × speed` so the frame under the edge does not move
 42	    /// (spec §6).
 43	    ///
 44	    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
 45	    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
 46	    /// D4-5) — and to leaving at least one frame of clip. Actions are
 47	    /// deliberately left alone: clip-relative, rebasing would drop or bake
 48	    /// whatever fell off the front, which is lossy and makes trimming back
 49	    /// out not an identity. On a RAMPED clip the actions keep their clip
 50	    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
 51	    /// rate moving out, and the edge is held where the clip still fits its
 52	    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
 53	    /// new start can change. `text.words` are the opposite, on purpose
 54	    /// (spec §11, W-3): a word is anchored to speech that stays where it is
 55	    /// on the timeline, so every word is rebased by the trim's delta and a
 56	    /// word trimmed off the front keeps its (negative) time. A graphic's
 57	    /// `in` advances by the same delta (road map 10's G-9), with no speed
 58	    /// and no head bound, never below 0.
 59	    ///
 60	    /// Without `alone`, a linked partner whose start is this clip's is
 61	    /// trimmed to the same `to` after it, by its own clamps; with it, the
 62	    /// clip moves alone — the J-cut (spec §11 AU-93, `carried_edge`).
 63	    pub fn trim_start(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
 64	        self.carried_edge(
 65	            clip,
 66	            alone,
 67	            |target, partner| partner.start == target.start,
 68	            |project, id| project.trim_start_one(id, to),
 69	        )
 70	    }
 71	
 72	    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
 73	        let target = self.require_clip(clip)?.clone();
 74	        let end = clip_end(&target);
 75	        let latest = end.saturating_sub(self.frame());
 76	        let mut to = self.snapped(to).min(latest).max(0);
 77	
 78	        if let Some(earliest) = self.earliest_start_on_grid(&target) {
 79	            to = to.max(earliest.max(0));
 80	        }
 81	        // A ramped clip's edge is held where the clip still fits its media
 82	        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
 83	        let to = self.front_edge_held(&target, to);
 84	        // The two clamps can cross when the source has almost nothing left
 85	        // in front: then there is no legal new start, so nothing happens.
 86	        if to > latest || to == target.start {
 87	            return Ok(Outcome::Identity);
 88	        }
 89	
 90	        let delta = to.saturating_sub(target.start);
 91	        let mut moved = target.clone();
 92	        moved.source = source_advanced_through(&target, delta);
 93	        moved.start = to;
 94	        moved.duration = end.saturating_sub(to);
 95	        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
 96	        if let Some(text) = moved.text.as_mut() {
 97	            rebase_words(text, delta);
 98	        }
 99	        self.commit_replacements(vec![moved])
100	    }
101	
102	    /// Moves the clip's end edge to `to`, clamped to the source's remaining
103	    /// length (media sources) and to at least one frame of clip (spec §6).
104	    /// The source in point and the actions are untouched. The bound is
105	    /// `source_window.rs`'s `latest_end_on_grid`, measured at this clip's
106	    /// OWN start: the last frame at or before the end of the file, and
107	    /// never the one past it (spec §11, #22 and D4-2). A ramped clip's bound
108	    /// reads its map on past the end (S∞, spec §11 SR-18 (a)). A graphic's
109	    /// `length` is untouched: null follows the new end, a number stays (G-9).
110	    /// `alone` is `trim_start`'s: without it a linked partner ending where
111	    /// this clip ends follows; with it, the L-cut (spec §11 AU-93).
112	    pub fn trim_end(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
113	        self.carried_edge(
114	            clip,
115	            alone,
116	            |target, partner| clip_end(partner) == clip_end(target),
117	            |project, id| project.trim_end_one(id, to),
118	        )
119	    }
120	
121	    fn trim_end_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
122	        let target = self.require_clip(clip)?.clone();
123	        let earliest = target.start.saturating_add(self.frame());
124	        let mut to = self.snapped(to).max(earliest);
125	        if let Some(latest) = self.latest_end_on_grid(&target) {
126	            to = to.min(latest);
127	        }
128	        if to < earliest || to == clip_end(&target) {
129	            return Ok(Outcome::Identity);
130	        }
131	
132	        let mut moved = target.clone();
133	        moved.duration = to.saturating_sub(target.start);
134	        self.commit_replacements(vec![moved])
135	    }
136	
137	    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
138	    /// source range it shows: `speed = source_len / (to_end - start)`
139	    /// (spec §6). Media sources only.
140	    ///
141	    /// An IDENTITY when the new length is under a frame or the resulting rate
142	    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
143	    /// breaks the overlap rule. Actions keep their clip-relative fraction.
144	    ///
145	    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
146	    /// start) through `scaled_profile`, so the ramp keeps its shape and its
147	    /// window; an f that would take any rate the clip names past the limits
148	    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
149	    /// Refused on a linked clip (spec §11 AU-94).
150	    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {
151	        let target = self.require_clip(clip)?.clone();
152	        if !matches!(target.source, Source::Media { .. }) {
153	            return Err(format!("clip {clip} is not a media clip"));
154	        }
155	        let to_end = self.snapped(to_end);
156	        let duration = to_end.saturating_sub(target.start);
157	        if duration < self.frame() {
158	            return Ok(Outcome::Identity);
159	        }
160	        if let Some((low, high)) = profile_factors(&target) {
161	            let factor = target.duration as f64 / duration as f64;
162	            if !factor.is_finite() || !(low..=high).contains(&factor) {
163	                return Ok(Outcome::Identity);
164	            }
165	            let moved = self.scaled_profile(&target, factor, duration);
166	            return self.commit_rate(&target, moved);
167	        }
168	        let rate = self.content_length_in_source(&target) as f64 / duration as f64;
169	        if !rate.is_finite() || !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
170	            return Ok(Outcome::Identity);
171	        }
172	
173	        let mut moved = target.clone();
174	        moved.speed = rate;
175	        moved.duration = duration;
176	        self.rescale_actions(&mut moved.actions, target.duration, duration);
177	        self.commit_rate(&target, moved)
178	    }
179	
180	    /// A rate edit's commit: refused on a linked clip whose rate it changes
181	    /// (spec §11 AU-94), else placed as any replacement is.
182	    fn commit_rate(&self, before: &Clip, moved: Clip) -> Result<Outcome, String> {
183	        if let Some(why) = self.linked_rate_refusal(before, &moved) {
184	            return Ok(Outcome::Refused(why));
185	        }
186	        self.commit_replacements(vec![moved])
187	    }
188	
189	    /// Sets the clip's playback rate: `duration = source_len / rate` held
190	    /// to what the file holds AT THAT RATE (`duration_at_speed`, spec §11
191	    /// D4-3), actions keeping their clip-relative fraction (spec §6). Media
192	    /// sources only; `keep_pitch`, when given, sets the time-pitch flag.
193	    ///
194	    /// Takes a `rate` or a `duration`, exactly one (spec §11 #190). A
195	    /// duration is the Fit arm: snapped to the grid, held to a frame, and
196	    /// turned into the rate that plays the clip's content in it; the current
197	    /// duration keeps the current rate, so it makes no phantom step.
198	    ///
199	    /// Either rate is clamped to `SPEED_MIN`–`SPEED_MAX` rather than
200	    /// refused, because a slider or an MCP call that asks for more wants the
201	    /// fastest thing available. `Err` for both or neither, a non-media clip,
202	    /// a rate that is not a positive finite number or a duration that is not
203	    /// positive; refuses on an overlap-rule violation.
204	    ///
205	    /// On a RAMPED clip the whole rate profile scales by one factor f — the
206	    /// clamped rate over the base, or D ÷ d — clamped so no rate the clip
207	    /// names passes a limit (`profile_factors`): the ramp keeps its shape
208	    /// and its window, and its base may stop short of the rate asked; when
209	    /// f does not clamp, the base is the clamped rate itself. The
210	    /// new duration is d, or snapped(round(D ÷ f)) when f clamped or the
211	    /// rate arm set it, held through `scaled_profile` (spec §11 SR-19 (a),
212	    /// (b)). An f of 1 changes nothing but `keep_pitch`. A linked clip's
213	    /// rate is refused (spec §11 AU-94); `keep_pitch` alone is not a rate.
214	    pub fn set_speed(
215	        &self,
216	        clip: u32,
217	        rate: Option<f64>,
218	        duration: Option<Ticks>,
219	        keep_pitch: Option<bool>,
220	    ) -> Result<Outcome, String> {
221	        match (rate, duration) {
222	            (Some(_), Some(_)) => {
223	                return Err(format!(
224	                    "set_speed takes a rate or a duration, not both (clip {clip})"
225	                ))
226	            }
227	            (None, None) => {
228	                return Err(format!(
229	                    "set_speed takes a rate or a duration (clip {clip})"
230	                ))
231	            }
232	            _ => {}
233	        }
234	        let target = self.require_clip(clip)?.clone();
235	        if !matches!(target.source, Source::Media { .. }) {
236	            return Err(format!("clip {clip} is not a media clip"));
237	        }
238	        if let Some(rate) = rate {
239	            if !(rate.is_finite() && rate > 0.0) {
240	                return Err(format!("speed must be a positive number, not {rate}"));
241	            }
242	        }
243	        if let Some(duration) = duration {
244	            if duration <= 0 {
245	                return Err(format!("duration must be positive, not {duration}"));
246	            }
247	        }
248	        if let Some((low, high)) = profile_factors(&target) {
249	            let frame = self.frame();
250	            let (asked, fitted) = match (rate, duration) {
251	                (Some(rate), _) => (rate.clamp(SPEED_MIN, SPEED_MAX) / target.speed, None),
252	                (None, Some(duration)) => {
253	                    let d = self.snapped(duration).max(frame);
254	                    if d == target.duration {
255	                        (1.0, None)
256	                    } else {
257	                        (target.duration as f64 / d as f64, Some(d))
258	                    }
259	                }
260	                (None, None) => (1.0, None),
261	            };
262	            let factor = asked.clamp(low, high);
263	            let length = match fitted {
264	                Some(d) if factor == asked => d,
265	                _ => {
266	                    let scaled = (target.duration as f64 / factor).round();
267	                    if scaled.is_finite() {
268	                        self.snapped(scaled as Ticks).max(frame)
269	                    } else {
270	                        target.duration
271	                    }
272	                }
273	            };
274	            let mut moved = self.scaled_profile(&target, factor, length);
275	            // An unclamped rate arm writes the rate asked itself: `speed ×
276	            // (rate ÷ speed)` can miss it by an ULP (spec §11 SR-19 (a)).
277	            if let (Some(rate), true) = (rate, factor == asked) {
278	                moved.speed = rate.clamp(SPEED_MIN, SPEED_MAX);
279	            }
280	            if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
281	                audio.keep_pitch = keep;
282	            }
283	            return self.commit_rate(&target, moved);
284	        }
285	        let rate = match (rate, duration) {
286	            (Some(rate), _) => rate,
287	            (None, Some(duration)) => {
288	                let d = self.snapped(duration).max(self.frame());
289	                if d == target.duration {
290	                    target.speed
291	                } else {
292	                    self.content_length_in_source(&target) as f64 / d as f64
293	                }
294	            }
295	            (None, None) => target.speed,
296	        };
297	        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);
298	
299	        let mut moved = target.clone();
300	        moved.speed = rate;
301	        moved.duration = self.duration_at_speed(&target, rate);
302	        self.rescale_actions(&mut moved.actions, target.duration, moved.duration);
303	        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
304	            audio.keep_pitch = keep;
305	        }
306	        self.commit_rate(&target, moved)
307	    }
308	}
 20	//!    Clips never push each other, and a shift never splits anything the
 21	//!    user did not ask to split.
 22	//!
 23	//! Everything here is composed from the primitives in `edit_clip.rs` —
 24	//! `split_clips`, `split_under_playhead`, `snapped`, `finish` — rather than
 25	//! restating them, so a split made by a range delete is the same split ⌘T
 26	//! makes.
 27	
 28	use crate::cursor_props::with_base_cursor;
 29	use crate::edit_clip::clip_end;
 30	use crate::model::{Clip, Enabled, Project, Source, VideoProps};
 31	use crate::outcome::Outcome;
 32	use crate::source_window::source_read_by;
 33	use crate::time::{Ticks, TIMESCALE};
 34	
 35	/// Default freeze length (spec §6). Two seconds is long enough for a hold
 36	/// to read as deliberate and short enough that the user trims it rather
 37	/// than deletes it.
 38	const DEFAULT_FREEZE_DURATION: Ticks = 2 * TIMESCALE;
 39	
 40	/// A half-open span of project time a ripple removes.
 41	#[derive(Debug, Clone, Copy)]
 42	struct Span {
 43	    start: Ticks,
 44	    end: Ticks,
 45	}
 46	
 47	/// The spans merged into disjoint ones, ascending.
 48	///
 49	/// Adjacent spans merge as well as overlapping ones: two clips that meet at
 50	/// a cut leave ONE hole, and shifting twice by two lengths is the same as
 51	/// shifting once by their sum only when the boundaries are handled in one
 52	/// piece. Empty spans are dropped — a zero-length hole moves nothing.
 53	fn union(mut spans: Vec<Span>) -> Vec<Span> {
 54	    spans.sort_by_key(|s| (s.start, s.end));
 55	    let mut out: Vec<Span> = Vec::new();
 56	    for span in spans {
 57	        if span.end <= span.start {
 58	            continue;
 59	        }
 60	        match out.last_mut() {

     1	//! `set_action_end`'s `speed` arm (format version 27, spec §11 SR-10), and
     2	//! the refusals every action op that can move a ramped clip's out point
     3	//! answers (SR-2, the road map's C).
     4	//!
     5	//! `speed` is a number at the TOP of an action's `end`, beside the groups:
     6	//! the rate the clip ramps to along the action's curve and holds after
     7	//! (`speed_map.rs`). It is a door of its own, as `graphic` is
     8	//! (`edit_action_graphic.rs`): not a property group, so `check_end_patch`
     9	//! steps over it and this file reads it. A finite number is clamped to
    10	//! ×0.1–×1000 as `set_speed` clamps; any other kind is an `Err`, and so is a
    11	//! rate on a clip that is not a media clip, which has no window to read at
    12	//! one; a `null` removes it, as it removes any key.
    13	//!
    14	//! **The clip keeps its slot** (SR-2): a ramp edit never moves `start` or
    15	//! `duration`, it changes how much source the clip reads, `in + S(D)`. An
    16	//! edit that would read past the media's end is REFUSED, naming what fits:
    17	//! the largest end rate (R1) — S(D) is affine in one action's end rate, so
    18	//! two readings solve it — or, when no rate down to ×0.1 fits, the latest
    19	//! clip end at ×0.1 (R2); and for a retime, a removal or an end rate taken
    20	//! away, the latest clip end (R3).
    21	
    22	use serde_json::Value;
    23	
    24	use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
    25	use crate::export::describe;
    26	use crate::model::{Clip, Project, Source};
    27	use crate::speed_map::SpeedMap;
    28	use crate::time::Ticks;
    29	
    30	/// Reads a patch's `speed` for `clip`: `None` for a `null` (remove it), the
    31	/// clamped rate for a number. `Err` for any other JSON kind, then for a
    32	/// clip that is not a media clip.
    33	pub(crate) fn read_speed_end(clip: &Clip, value: &Value) -> Result<Option<f64>, String> {
    34	    if value.is_null() {
    35	        return Ok(None);
    36	    }
    37	    let Some(rate) = value.as_f64() else {
    38	        return Err(format!("speed must be a number, not {}", describe(value)));
    39	    };
    40	    if !matches!(clip.source, Source::Media { .. }) {
    41	        return Err(format!(
    42	            "clip {} is not a media clip, and only a media clip's action can end at a speed",
    43	            clip.id
    44	        ));
    45	    }
    46	    Ok(Some(rate.clamp(SPEED_MIN, SPEED_MAX)))
    47	}
    48	
    49	/// `clip` with action `action`'s end rate set to `rate`.
    50	fn ending_at(clip: &Clip, action: u32, rate: f64) -> Clip {
    51	    let mut out = clip.clone();
    52	    if let Some(found) = out.actions.iter_mut().find(|a| a.id == action) {
    53	        if let Value::Object(end) = &mut found.end {
    54	            end.insert("speed".to_string(), Value::from(rate));
    55	        }
    56	    }
    57	    out
    58	}
    59	
    60	/// The `{}` a refusal names a rate in, on the 0.001 grid it was found on.
    61	fn thousandths(k: i64) -> f64 {
    62	    k as f64 / 1000.0
    63	}
    64	
    65	impl Project {
    66	    /// The latest clip END that fits: the clip's start plus S⁻¹ of what the
    67	    /// file holds past `in`, snapped DOWN onto the grid, never before the
    68	    /// start.
    69	    fn latest_fitting_end(&self, clip: &Clip) -> Ticks {
    70	        let Some((source_in, file)) = self.window_of(clip) else {
    71	            return clip.start;
    72	        };
    73	        let remaining = file.saturating_sub(source_in).max(0) as f64;
    74	        let fits = match SpeedMap::of(clip) {
    75	            Some(map) => map.time_at(remaining),
    76	            None if clip.speed.is_finite() && clip.speed > 0.0 => {
    77	                let t = (remaining / clip.speed).floor();
    78	                if t.is_finite() {
    79	                    t as Ticks
    80	                } else {
    81	                    0
    82	                }
    83	            }
    84	            None => remaining as Ticks,
    85	        };
    86	        self.snapped_down(clip.start.saturating_add(fits))
    87	            .max(clip.start)
    88	    }
    89	
    90	    /// The largest end rate on the 0.001 grid, below `rate`, at which
    91	    /// action `action` of `after` reads inside its file: R1's solve, then
    92	    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
    93	    /// a split's second half (spec §11 SR-18 (e)).
    94	    pub(crate) fn largest_fitting_end_rate(
    95	        &self,
    96	        after: &Clip,
    97	        action: u32,
    98	        rate: f64,
    99	    ) -> Option<f64> {
   100	        let floor = (SPEED_MIN * 1000.0).round() as i64;
   101	        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
   102	    }
   103	
   104	    /// The largest rate x on the 0.001 grid, below `rate` and at or above
   105	    /// `floor_k` thousandths, at which the clip `at_rate(x)` reads inside
   106	    /// its file: R1's solve, then its step down. `None` when none does.
   107	    /// `at_rate` must make S(D) affine in x — one action's end rate
   108	    /// (`largest_fitting_end_rate`), or a preset's target, which every
   109	    /// piece it builds ramps to, holds or ramps from (`add_speed_ramp`,
   110	    /// spec §11 SR-23 (g)).
   111	    pub(crate) fn largest_fitting_rate(
   112	        &self,
   113	        at_rate: &dyn Fn(f64) -> Clip,
   114	        rate: f64,
   115	        floor_k: i64,
   116	    ) -> Option<f64> {
   117	        let probe = at_rate(rate);
   118	        let (source_in, file) = self.window_of(&probe)?;
   119	        let fits = |x: f64| self.overrun(&at_rate(x)).is_none();
   120	        // S(D) = α + β·x in the rate x: read at two rates in range, solved
   121	        // for the file's remainder.
   122	        let read = |x: f64| SpeedMap::of(&at_rate(x)).map(|m| m.source_at(probe.duration));
   123	        let solved = match (read(SPEED_MIN), read(1.0)) {
   124	            (Some(low), Some(one)) => {
   125	                let beta = (one - low) / (1.0 - SPEED_MIN);
   126	                let alpha = low - SPEED_MIN * beta;
   127	                let remaining = file.saturating_sub(source_in) as f64;
   128	                (beta > 0.0).then(|| (remaining - alpha) / beta)
   129	            }
   130	            _ => None,
   131	        };
   132	        let x = solved.filter(|x| x.is_finite())?;
   133	        // Floored to 0.001, never at or above the rate that overran, then
   134	        // stepped down a thousandth until it fits. The millionth keeps a
   135	        // solve that lands a hair under an exact thousandth (×4 read as
   136	        // 3.9999999) on it; the step down catches the rest.
